                Ubicaciâ”œâ”‚n: {locations.find(l=>l.id===a.location_id)?.name || a.location_id}
                {a.serial_number && ` Ã”Ã‡Ã³ Serie: ${a.serial_number}`}
                {a.qr_code && ` Ã”Ã‡Ã³ QR: ${a.qr_code}`}
              </div>
            </Link>
          </li>))}
        </ul>
      )}
    </div>
  );
}

"use client";

import { theme } from "@/lib/theme";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { api } from "@/lib/api";
