"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { theme } from "@/lib/theme";
import { ThemeToggle } from "@/components/ThemeToggle";

const navItems = [
  { href: "/dashboard", label: "Panel", icon: "Â­Æ’Ã…Ã¡", exact: true },
  { href: "/dashboard/ot", label: "â”œÃ´rdenes de Trabajo", icon: "Â­Æ’ÂºÂ¥" },
  { href: "/dashboard/customers", label: "Clientes", icon: "Â­Æ’Ã¦Ã‘" },
  { href: "/dashboard/technicians", label: "Tâ”œÂ®cnicos", icon: "Â­Æ’Ã¶Âº" },
  { href: "/dashboard/locations", label: "Ubicaciones", icon: "Â­Æ’Ã´Ã¬" },
  { href: "/dashboard/assets", label: "Activos", icon: "Ã”ÃœÃ–Â´Â©Ã…" },
];

export default function DashboardLayout({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const [authed, setAuthed] = useState(false);
  const [checking, setChecking] = useState(true);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const token = localStorage.getItem("access_token");
    if (!token) { window.location.href = "/login"; return; }
    setAuthed(true); setChecking(false);
  }, []);

  // El nav mobile se cierra solo al cambiar de ruta, para no quedar
  // abierto tapando la pantalla siguiente.
  useEffect(() => { setMenuOpen(false); }, [pathname]);

  if (checking) return <div style={{ padding: "2rem", textAlign: "center", color: theme.textSecondary }}>Cargando...</div>;
  if (!authed) return null;

  return (
    <div style={{ minHeight: "100vh", display: "flex", flexDirection: "column", background: theme.bg }}>
      <header style={{ background: theme.headerBg, color: theme.headerText, padding: "0.75rem 1rem", position: "sticky", top: 0, zIndex: 10 }}>
        <div style={{ maxWidth: "1200px", margin: "0 auto", position: "relative", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <Link href="/dashboard" style={{ fontWeight: 700, fontSize: "1.25rem", color: theme.headerText, textDecoration: "none" }}>gi-ot</Link>

          <div style={{ display: "flex", alignItems: "center", gap: "0.5rem" }}>
          <ThemeToggle />
          <button
            onClick={() => setMenuOpen((v) => !v)}
            aria-label={menuOpen ? "Cerrar menâ”œâ•‘" : "Abrir menâ”œâ•‘"}
            aria-expanded={menuOpen}
            className="dashboard-nav-toggle"
            style={{ background: "transparent", border: "1px solid " + theme.headerActive, color: theme.headerText, borderRadius: "0.375rem", padding: "0.5rem 0.75rem", fontSize: "1rem", cursor: "pointer", alignItems: "center", justifyContent: "center" }}
          >
            {menuOpen ? "Ã”Â£Ã²" : "Ã”Ã¿â–‘"}
          </button>
          </div>

          <nav className={`dashboard-nav${menuOpen ? " open" : ""}`}>
            {navItems.map(item => {
              const active = item.exact ? pathname === item.href : pathname.startsWith(item.href);
              return (
                <Link key={item.href} href={item.href} style={{
                  padding: "0.5rem 1rem", borderRadius: "0.375rem",
                  background: active ? theme.headerActive : "transparent",
                  color: theme.headerText, textDecoration: "none", fontSize: "0.875rem", display: "flex", alignItems: "center", gap: "0.375rem"
                }}>
                  {item.icon} {item.label}
                </Link>
              );
            })}
            <button onClick={() => { localStorage.removeItem("access_token"); window.location.href = "/login"; }}
              style={{ padding: "0.5rem 1rem", background: "transparent", border: "1px solid " + theme.headerActive, color: theme.headerText, borderRadius: "0.375rem", cursor: "pointer" }}>
              Salir
            </button>
          </nav>
        </div>
      </header>
      <main style={{ flex: 1, padding: "1rem", maxWidth: "1200px", margin: "0 auto", width: "100%", color: theme.text }}>
        {children}
      </main>
    </div>
  );
}

"use client";

import { theme } from "@/lib/theme";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { api } from "@/lib/api";
import { ErrorBanner } from "@/components/ErrorBanner";
import { SuccessBanner } from "@/components/SuccessBanner";
import { Location, Customer } from "@/lib/types";

export default function LocationDetailPage() {
  const params = useParams(); const router = useRouter(); const id = params.id as string;
  const [loc, setLoc] = useState<Location | null>(null);
  const [customer, setCustomer] = useState<Customer | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [editMode, setEditMode] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const [form, setForm] = useState({ name: "", address: "", city: "", province: "", notes: "" });

  useEffect(() => { load(); }, [id]);

  async function load() {
    try {
      setLoading(true);
      const [locData, custData] = await Promise.all([
        api.get<Location>(`/locations/${id}`),
        api.get<Customer[]>("/customers"),
      ]);
      setLoc(locData);
      setForm({ name: locData.name, address: locData.address || "", city: locData.city || "", province: locData.province || "", notes: locData.notes || "" });
      setCustomer(custData.find(c => c.person_id === locData.customer_id) || null);
    } catch (e) { setError(e instanceof Error ? e.message : "Error al cargar"); }
    finally { setLoading(false); }
  }

  async function save() {
    try {
      setSaving(true); setError(null);
      await api.patch(`/locations/${id}`, form);
      await load();
      setEditMode(false);
      setSuccessMessage("Ubicaciâ”œâ”‚n actualizada.");
      setTimeout(() => setSuccessMessage(null), 3000);
    }
    catch (e) { setError(e instanceof Error ? e.message : "Error al guardar"); }
    finally { setSaving(false); }
  }

  if (loading) return <div style={{ padding: "1rem", textAlign: "center" }}>Cargando...</div>;
  if (!loc) return <div style={{ padding: "1rem" }}>No encontrado</div>;

  return (
    <div style={{ padding: "1rem", maxWidth: "700px", margin: "0 auto" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1rem" }}>
        <h1>{loc.name}</h1>
        <div style={{ display: "flex", gap: "0.5rem" }}>
          <button onClick={()=>setEditMode(!editMode)} style={{ padding: "0.5rem 1rem" }}>{editMode?"Cancelar":"Editar"}</button>
          <button onClick={()=>router.back()} style={{ padding: "0.5rem 1rem", background: theme.bg }}>Volver</button>
        </div>
      </div>
      {error && <ErrorBanner message={error} onRetry={load} />}
      {successMessage && <SuccessBanner message={successMessage} />}
      <div style={{ border: `1px solid ${theme.border}`, borderRadius: "0.5rem", padding: "1rem" }}>
        <dl style={{ display: "grid", gridTemplateColumns: "120px 1fr", gap: "0.5rem 1rem" }}>
          <dt>Direcciâ”œâ”‚n</dt><dd>{loc.address || "Ã”Ã‡Ã¶"}</dd>
          <dt>Ciudad</dt><dd>{loc.city || "Ã”Ã‡Ã¶"}</dd>
          <dt>Provincia</dt><dd>{loc.province || "Ã”Ã‡Ã¶"}</dd>
          <dt>Cliente</dt><dd>{customer?.display_name || loc.customer_id}</dd>
          <dt>Observaciones</dt><dd>{loc.notes || "Ã”Ã‡Ã¶"}</dd>
        </dl>
        {editMode && (
          <div style={{ marginTop: "1rem", display: "grid", gap: "0.75rem" }}>
            <input value={form.name} onChange={e=>setForm({...form, name: e.target.value})} style={{ width: "100%", padding: "0.5rem" }} />
            <input value={form.address} onChange={e=>setForm({...form, address: e.target.value})} style={{ width: "100%", padding: "0.5rem" }} />
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "1rem" }}>
              <input value={form.city} onChange={e=>setForm({...form, city: e.target.value})} placeholder="Ciudad" style={{ width: "100%", padding: "0.5rem" }} />
              <input value={form.province} onChange={e=>setForm({...form, province: e.target.value})} placeholder="Provincia" style={{ width: "100%", padding: "0.5rem" }} />
            </div>
            <textarea value={form.notes} onChange={e=>setForm({...form, notes: e.target.value})} rows={3} style={{ width: "100%", padding: "0.5rem" }} placeholder="Observaciones" />
            <div style={{ display: "flex", justifyContent: "flex-end" }}>
              <button onClick={save} disabled={saving} style={{ padding: "0.5rem 1.5rem", background: theme.primary, color: theme.primaryText, border: "none", borderRadius: "0.375rem" }}>{saving?"Guardando...":"Guardar"}</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

