          <Link href="/dashboard/locations" style={{ flex: 1, padding: "1rem", background: theme.bg, textAlign: "center", textDecoration: "none", borderRadius: "0.5rem" }}>Cancelar</Link>
        </div>
      </form>
    </div>
  );
}

