"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { api } from "@/lib/api";
import { theme } from "@/lib/theme";
import { WorkOrder } from "@/lib/types";
import { ErrorBanner } from "@/components/ErrorBanner";

interface Indicator {
  key: string;
  label: string;
  count: number;
  href: string;
  fg: string;
  bg: string;
}

// Panel principal de Oficina/Admin (ROADMAP â”¬Âº07): orientado a situaciâ”œâ”‚n
// operativa, no a navegaciâ”œâ”‚n Ã”Ã‡Ã¶ cada indicador lleva al subconjunto de OT
// correspondiente en el listado (UI-UX-STANDARDS â”¬Âº33: reconocer Ã”Ã¥Ã† decidir Ã”Ã¥Ã† actuar).
export default function DashboardPanelPage() {
  const [wos, setWos] = useState<WorkOrder[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  async function loadWos() {
    try {
      setLoading(true); setError(null);
      const data = await api.get<WorkOrder[]>("/work-orders");
      setWos(data);
    } catch (e) { setError(e instanceof Error ? e.message : "Error al cargar el panel"); }
    finally { setLoading(false); }
  }

  useEffect(() => {
    loadWos();
  }, []);

  const indicators: Indicator[] = useMemo(() => {
    const pending = wos.filter((w) => w.status_code === "PENDING").length;
    const inProgress = wos.filter((w) => w.status_code === "IN_PROGRESS").length;
    const urgent = wos.filter((w) => w.priority_code === "URGENT" && !w.is_terminal).length;
    const unresolved = wos.filter((w) => w.status_code === "UNRESOLVED").length;
    return [
      { key: "pending", label: "Pendientes", count: pending, href: "/dashboard/ot?status=PENDING", fg: theme.success, bg: theme.successBg },
      { key: "in_progress", label: "En curso", count: inProgress, href: "/dashboard/ot?status=IN_PROGRESS", fg: theme.warning, bg: theme.warningBg },
      { key: "urgent", label: "Urgentes", count: urgent, href: "/dashboard/ot?priority_code=URGENT", fg: theme.danger, bg: theme.dangerBg },
      { key: "unresolved", label: "Requieren atenciâ”œâ”‚n", count: unresolved, href: "/dashboard/ot?status=UNRESOLVED", fg: theme.danger, bg: theme.dangerBg },
    ];
  }, [wos]);

  const openCount = wos.filter((w) => !w.is_terminal).length;

  return (
    <div style={{ maxWidth: "1200px", margin: "0 auto" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1.25rem", flexWrap: "wrap", gap: "0.75rem" }}>
        <div>
          <h1 style={{ color: theme.text }}>Panel</h1>
          <p style={{ color: theme.textSecondary, fontSize: "0.9375rem", marginTop: "0.125rem" }}>
            {loading ? "Cargando situaciâ”œâ”‚n operativa..." : `${openCount} OT abiertas en total`}
          </p>
        </div>
        <Link href="/dashboard/ot/new" style={{ textDecoration: "none" }}>
          <button style={{ background: theme.successSolid, color: theme.primaryText, border: "none", padding: "0.75rem 1.5rem", borderRadius: "0.5rem", fontSize: "1rem", cursor: "pointer", fontWeight: 600 }}>
            + Nueva OT
          </button>
        </Link>
      </div>

      {error && <ErrorBanner message={error} onRetry={loadWos} />}

      {loading ? (
        <div style={{ textAlign: "center", padding: "3rem", color: theme.textSecondary }}>Cargando...</div>
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: "0.875rem", marginBottom: "1.5rem" }}>
          {indicators.map((ind) => (
            <Link key={ind.key} href={ind.href} style={{ textDecoration: "none" }}>
              <div style={{ background: theme.surface, border: `1px solid ${theme.border}`, borderRadius: "0.75rem", padding: "1.25rem" }}>
                <div style={{ fontSize: "2rem", fontWeight: 700, color: ind.fg }}>{ind.count}</div>
                <div style={{ marginTop: "0.25rem", fontSize: "0.9375rem", color: theme.text }}>{ind.label}</div>
              </div>
            </Link>
          ))}
        </div>
      )}

      <Link href="/dashboard/ot" style={{ color: theme.primary, fontSize: "0.9375rem", textDecoration: "underline" }}>
        Ver todas las â”œÃ´rdenes de Trabajo Ã”Ã¥Ã†
      </Link>
    </div>
  );
}

"use client";

import { theme } from "@/lib/theme";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { api } from "@/lib/api";
import { ErrorBanner } from "@/components/ErrorBanner";
import { SuccessBanner } from "@/components/SuccessBanner";
import { Technician, TechnicianUpdate, UserAccount } from "@/lib/types";

export default function TechnicianDetailPage() {
  const params = useParams(); const router = useRouter(); const personId = params.id as string;
  const [tech, setTech] = useState<Technician | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [editMode, setEditMode] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const [form, setForm] = useState<TechnicianUpdate>({
    person_type: "INDIVIDUAL", display_name: "", address: "", phone: "", email: "", notes: "",
    status: "ACTIVE", profession: "", license_number: "", commission_percentage: 0, technician_status: "ACTIVE"
  });

  // Vâ”œÂ¡nculo Tâ”œÂ®cnico Ã”Ã¥Ã¶ Usuario (ROADMAP â”¬Âº06 Ã”Ã‡Ã¶ necesario para que el
  // tâ”œÂ®cnico pueda loguearse y usar /tecnico). GET /users es solo para
  // TENANT_ADMIN; si el usuario logueado es TENANT_OFFICE la lista
  // queda vacâ”œÂ¡a y se oculta el selector, sin romper la pâ”œÃ­gina.
  const [users, setUsers] = useState<UserAccount[]>([]);
  const [canManageUsers, setCanManageUsers] = useState(true);
  const [selectedUserId, setSelectedUserId] = useState("");
  const [linking, setLinking] = useState(false);
  const [newUserEmail, setNewUserEmail] = useState("");
  const [newUserName, setNewUserName] = useState("");
  const [newUserPassword, setNewUserPassword] = useState("");
  const [creatingUser, setCreatingUser] = useState(false);

  useEffect(() => { load(); loadUsers(); }, [personId]);

  async function load() {
    try {
      setLoading(true);
      const data = await api.get<Technician>(`/technicians/${personId}`);
      setTech(data);
      setForm({ person_type: data.person_type, display_name: data.display_name, address: data.address || "", phone: data.phone || "", email: data.email || "", notes: data.notes || "", status: data.status, profession: data.profession || "", license_number: data.license_number || "", commission_percentage: data.commission_percentage || 0, technician_status: data.technician_status });
    } catch (e) { setError(e instanceof Error ? e.message : "Error al cargar"); }
    finally { setLoading(false); }
  }

  async function loadUsers() {
    try {
      const list = await api.get<UserAccount[]>("/users");
      setUsers(list.filter((u) => u.role_code === "TENANT_TECHNICIAN"));
    } catch {
      setCanManageUsers(false);
    }
  }

  async function save() {
    try {
      setSaving(true); setError(null);
      await api.patch(`/technicians/${personId}`, form);
      await load();
      setEditMode(false);
      setSuccessMessage("Tâ”œÂ®cnico actualizado.");
      setTimeout(() => setSuccessMessage(null), 3000);
    }
    catch (e) { setError(e instanceof Error ? e.message : "Error al guardar"); }
    finally { setSaving(false); }
  }

  async function linkUser(userId: string | null) {
    try {
      setLinking(true); setError(null);
      await api.patch(`/technicians/${personId}/user`, { user_id: userId });
      setSelectedUserId("");
      await load();
    } catch (e) { setError(e instanceof Error ? e.message : "Error al vincular usuario"); }
    finally { setLinking(false); }
  }

  async function createAndLinkUser() {
    try {
      setCreatingUser(true); setError(null);
      const user = await api.post<UserAccount>("/users", {
        email: newUserEmail, full_name: newUserName, password: newUserPassword, role_code: "TENANT_TECHNICIAN",
      });
      await api.patch(`/technicians/${personId}/user`, { user_id: user.id });
      setNewUserEmail(""); setNewUserName(""); setNewUserPassword("");
      await loadUsers();
      await load();
    } catch (e) { setError(e instanceof Error ? e.message : "Error al crear/vincular usuario"); }
    finally { setCreatingUser(false); }
  }

  if (loading) return <div style={{ padding: "1rem", textAlign: "center" }}>Cargando...</div>;
  if (error && !tech) return <div style={{ padding: "1rem", color: theme.danger }}>{error}</div>;
  if (!tech) return <div style={{ padding: "1rem" }}>No encontrado</div>;

  return (
    <div style={{ padding: "1rem", maxWidth: "800px", margin: "0 auto" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1rem" }}>
        <h1>{tech.display_name}</h1>
        <div style={{ display: "flex", gap: "0.5rem" }}>
          <button onClick={()=>setEditMode(!editMode)} style={{ padding: "0.5rem 1rem" }}>{editMode?"Cancelar":"Editar"}</button>
          <button onClick={()=>router.back()} style={{ padding: "0.5rem 1rem", background: theme.bg }}>Volver</button>
        </div>
      </div>
      {error && <ErrorBanner message={error} onRetry={load} />}
      {successMessage && <SuccessBanner message={successMessage} />}
      <div style={{ display: "grid", gap: "1rem" }}>
        <div style={{ border: `1px solid ${theme.border}`, borderRadius: "0.5rem", padding: "1rem" }}>
          <h3 style={{ marginBottom: "0.75rem" }}>Identificaciones</h3>
          <div style={{ display: "flex", flexWrap: "wrap", gap: "0.5rem" }}>
            {tech.identifications.map(i=>(<span key={i.id} style={{ background: i.is_primary?theme.infoBg:theme.bg, color: theme.text, padding: "0.25rem 0.75rem", borderRadius: "9999px", fontSize: "0.875rem" }}>{i.identification_type}: {i.identification_value} {i.is_primary&&"(principal)"}</span>))}
          </div>
        </div>
        <div style={{ border: `1px solid ${theme.border}`, borderRadius: "0.5rem", padding: "1rem" }}>
          <h3 style={{ marginBottom: "0.75rem" }}>Datos</h3>
          {editMode ? (
