    (async () => {
      for (const p of photos) {
        try {
          const blob = await api.getBlob(`/work-orders/${id}/photos/${p.id}/file`);
          if (cancelled) return;
          urls[p.id] = URL.createObjectURL(blob);
        } catch (e) { console.error(e); }
      }
      if (!cancelled) setPhotoUrls(urls);
