"use client";

import { useEffect, useState } from "react";
import { theme } from "@/lib/theme";

type ThemeChoice = "light" | "dark" | "system";

function applyTheme(choice: ThemeChoice) {
  const root = document.documentElement;
  if (choice === "system") root.removeAttribute("data-theme");
  else root.setAttribute("data-theme", choice);
}

// Toggle manual de tema claro/oscuro (ROADMAP â”¬Âº07 Ã”Ã‡Ã¶ "Tema claro/oscuro").
// Hasta ahora la app solo seguâ”œÂ¡a prefers-color-scheme del sistema, sin
// forma de elegir manualmente. Guarda la preferencia en localStorage;
// el script inline en layout.tsx aplica el valor guardado antes del
// primer pintado para evitar parpadeo.
export function ThemeToggle() {
  const [choice, setChoice] = useState<ThemeChoice>("system");

  useEffect(() => {
    try {
      const saved = localStorage.getItem("gi-ot-theme") as ThemeChoice | null;
      if (saved) setChoice(saved);
    } catch {
      // localStorage puede no estar disponible (modo privado); queda en "system".
    }
  }, []);

  function cycle() {
    const next: ThemeChoice = choice === "system" ? "light" : choice === "light" ? "dark" : "system";
    setChoice(next);
    applyTheme(next);
    try { localStorage.setItem("gi-ot-theme", next); } catch { /* ignorar */ }
  }

  const icon = choice === "light" ? "Ã”Ã¿Ã‡Â´Â©Ã…" : choice === "dark" ? "Â­Æ’Ã®Ã–" : "Â­Æ’Ã»Ã‘Â´Â©Ã…";
  const label = choice === "light" ? "Tema: claro" : choice === "dark" ? "Tema: oscuro" : "Tema: automâ”œÃ­tico";

  return (
    <button
      onClick={cycle}
      aria-label={`${label}. Tocar para cambiar.`}
      title={label}
      style={{ padding: "0.375rem 0.625rem", background: "transparent", border: `1px solid ${theme.headerActive}`, color: theme.headerText, borderRadius: "0.375rem", cursor: "pointer", fontSize: "0.9375rem", lineHeight: 1 }}
    >
      {icon}
    </button>
  );
}

const API_BASE = process.env.NEXT_PUBLIC_API_BASE || "http://localhost:8000/api/v1";

async function getToken(): Promise<string | null> {
  if (typeof window === "undefined") return null;
  return localStorage.getItem("access_token");
}

async function fetchWithAuth<T>(path: string, options: RequestInit = {}): Promise<T> {
  const token = await getToken();
  const headers: HeadersInit = {
    "Content-Type": "application/json",
    ...(options.headers || {}),
  };
  if (token) {
    (headers as Record<string, string>)["Authorization"] = `Bearer ${token}`;
  }

  const res = await fetch(`${API_BASE}${path}`, {
    ...options,
    headers,
  });

  if (res.status === 401) {
    if (typeof window !== "undefined") {
      localStorage.removeItem("access_token");
      window.location.href = "/login";
    }
    throw new Error("Unauthorized");
  }

  if (!res.ok) {
    const error = await res.json().catch(() => ({ detail: "Error desconocido" }));
    throw new Error(error.detail || `HTTP ${res.status}`);
  }

  if (res.status === 204) return undefined as T;
  return res.json();
}

async function fetchBlobWithAuth(path: string): Promise<Blob> {
  const token = await getToken();
  const headers: HeadersInit = token ? { Authorization: `Bearer ${token}` } : {};
  const res = await fetch(`${API_BASE}${path}`, { headers });
  if (res.status === 401) {
    if (typeof window !== "undefined") {
      localStorage.removeItem("access_token");
      window.location.href = "/login";
    }
    throw new Error("Unauthorized");
  }
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.blob();
}

async function upload<T>(path: string, formData: FormData): Promise<T> {
  const token = await getToken();
  const headers: HeadersInit = token ? { Authorization: `Bearer ${token}` } : {};
  const res = await fetch(`${API_BASE}${path}`, { method: "POST", headers, body: formData });
  if (res.status === 401) {
    if (typeof window !== "undefined") {
      localStorage.removeItem("access_token");
      window.location.href = "/login";
    }
    throw new Error("Unauthorized");
  }
  if (!res.ok) {
    const error = await res.json().catch(() => ({ detail: "Error desconocido" }));
    throw new Error(error.detail || `HTTP ${res.status}`);
  }
  return res.json();
}

export const api = {
  get: <T>(path: string) => fetchWithAuth<T>(path, { method: "GET" }),
  post: <T>(path: string, body: unknown) =>
    fetchWithAuth<T>(path, { method: "POST", body: JSON.stringify(body) }),
  patch: <T>(path: string, body: unknown) =>
    fetchWithAuth<T>(path, { method: "PATCH", body: JSON.stringify(body) }),
  delete: <T>(path: string) => fetchWithAuth<T>(path, { method: "DELETE" }),
  getBlob: (path: string) => fetchBlobWithAuth(path),
  upload: <T>(path: string, formData: FormData) => upload<T>(path, formData),
};

// --- Auth ---
export async function login(email: string, password: string): Promise<string> {
  const res = await fetch(`${API_BASE}/auth/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
  });
  if (!res.ok) throw new Error("Credenciales invâ”œÃ­lidas");
  const data = await res.json();
  if (typeof window !== "undefined") {
    localStorage.setItem("access_token", data.access_token);
  }
  return data.access_token;
}

export function logout() {
  if (typeof window !== "undefined") {
    localStorage.removeItem("access_token");
    window.location.href = "/login";
  }
}
